"""
Starter templates for `env-sentry init --template`.

Each template is a commented ``.env.example`` with the keys a fresh project
of that stack actually needs. Values are placeholders — never secrets.
"""

from __future__ import annotations

from typing import Dict, List, Tuple

GENERIC = """# Copy this file to .env and fill in real values.
# Generated by env-sentry.
APP_NAME=my-app
APP_ENV=development
APP_DEBUG=false
APP_URL=https://example.com

# --- secrets -------------------------------------------------------
# Generate strong values with: env-sentry gen
API_KEY=your_api_key_here

# --- database ------------------------------------------------------
DATABASE_URL=postgres://user:password@localhost:5432/app
"""

FASTAPI = """# FastAPI / Starlette
APP_NAME=my-api
APP_ENV=development
DEBUG=false
SECRET_KEY=your_secret_key_here
ALLOWED_ORIGINS=http://localhost:3000

DATABASE_URL=postgresql+asyncpg://user:password@localhost:5432/app
REDIS_URL=redis://localhost:6379/0

# Generate with: env-sentry gen
JWT_SECRET=your_jwt_secret_here
JWT_ALGORITHM=HS256
ACCESS_TOKEN_EXPIRE_MINUTES=30
"""

DJANGO = """# Django
DJANGO_SETTINGS_MODULE=config.settings.development
DEBUG=false
SECRET_KEY=your_django_secret_key_here
ALLOWED_HOSTS=localhost,127.0.0.1
CSRF_TRUSTED_ORIGINS=http://localhost:8000

DATABASE_URL=postgres://user:password@localhost:5432/app
REDIS_URL=redis://localhost:6379/0

EMAIL_HOST=smtp.example.com
EMAIL_PORT=587
EMAIL_HOST_USER=you@example.com
EMAIL_HOST_PASSWORD=your_email_password_here
"""

NEXTJS = """# Next.js
NEXT_PUBLIC_APP_URL=http://localhost:3000
NODE_ENV=development

# Server-only values (never prefix these with NEXT_PUBLIC_)
DATABASE_URL=postgres://user:password@localhost:5432/app
NEXTAUTH_URL=http://localhost:3000
NEXTAUTH_SECRET=your_nextauth_secret_here
"""

NODE = """# Node.js
NODE_ENV=development
PORT=3000
LOG_LEVEL=info

DATABASE_URL=postgres://user:password@localhost:5432/app
REDIS_URL=redis://localhost:6379

JWT_SECRET=your_jwt_secret_here
SESSION_SECRET=your_session_secret_here
"""

RAILS = """# Ruby on Rails
RAILS_ENV=development
RAILS_MASTER_KEY=your_rails_master_key_here
SECRET_KEY_BASE=your_secret_key_base_here

DATABASE_URL=postgres://user:password@localhost:5432/app_development
REDIS_URL=redis://localhost:6379/0
"""

LARAVEL = """# Laravel
APP_NAME=Laravel
APP_ENV=local
APP_DEBUG=true
APP_URL=http://localhost

DB_CONNECTION=pgsql
DB_HOST=127.0.0.1
DB_PORT=5432
DB_DATABASE=laravel
DB_USERNAME=root
DB_PASSWORD=your_db_password_here

MAIL_MAILER=smtp
MAIL_HOST=smtp.example.com
MAIL_PORT=587
MAIL_USERNAME=you@example.com
MAIL_PASSWORD=your_mail_password_here
"""

GO = """# Go service
APP_ENV=development
HTTP_ADDR=:8080
LOG_LEVEL=debug

DATABASE_URL=postgres://user:password@localhost:5432/app
REDIS_ADDR=localhost:6379

API_TOKEN=your_api_token_here
"""

DOCKER = """# Docker Compose / local stack
COMPOSE_PROJECT_NAME=myapp
POSTGRES_USER=app
POSTGRES_PASSWORD=your_postgres_password_here
POSTGRES_DB=app
POSTGRES_PORT=5432

REDIS_PORT=6379
APP_PORT=8000
"""

TEMPLATES: Dict[str, Tuple[str, str]] = {
    "generic": ("Generic starter", GENERIC),
    "fastapi": ("FastAPI / Starlette API", FASTAPI),
    "django": ("Django web app", DJANGO),
    "nextjs": ("Next.js app router", NEXTJS),
    "node": ("Node.js service", NODE),
    "rails": ("Ruby on Rails", RAILS),
    "laravel": ("Laravel (PHP)", LARAVEL),
    "go": ("Go service", GO),
    "docker": ("Docker Compose stack", DOCKER),
}


def names() -> List[str]:
    return sorted(TEMPLATES)


def render(name: str = "generic") -> str:
    if name not in TEMPLATES:
        raise ValueError(f"unknown template '{name}' (choose from {', '.join(names())})")
    _, body = TEMPLATES[name]
    return body if body.endswith("\n") else body + "\n"


def describe(name: str) -> str:
    return TEMPLATES[name][0]
